from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class MeanReversion10d(Strategy):
    rationale = (
        "Mean reversion strategies seek to profit from deviations from the mean. "
        "In this case, we look for stocks that have moved away from their recent average price and are likely to revert."
    )

    def __init__(self, window: int = 10) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        mean_close = (
            history.group_by("symbol")
                   .agg(pl.col("adj_close").mean().alias("mean_close"))
                   .with_columns((pl.col("adj_close") - pl.col("mean_close")).abs().alias("deviation"))
        )

        picks: list[str] = []
        for symbol in view.symbols:
            if symbol not in mean_close.columns or str(symbol) not in history.columns:
                continue
            deviation = float(mean_close.filter(pl.col("symbol") == symbol)["deviation"].item())
            if deviation >= 0.15:
                picks.append(symbol)

        if not picks:
            return Signal(information_available_at=stamp, weights={})
        weight = 1.0 / len(picks)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in picks},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
